mapper.select:
	with htmlreport as (
	select '01' reportcode,'CHB_PRD_DECLARE' htmlindex from dual
	union all select '02' reportcode,'CHB_PRD_BONUS_DEAL' htmlindex from dual


	union all select '04' reportcode,'MST_HOLIDAY' htmlindex from dual
	union all select '05' reportcode,'CHB_PRD_BASEINFO' htmlindex from dual
	union all select '06' reportcode,'CHB_PRD_DEAL' htmlindex from dual
	union all select '07' reportcode,'CHB_COUNTER_PARTY' htmlindex from dual
	union all select '08' reportcode,'CHB_PRD_OPENSCH' htmlindex from dual
	union all select '09' reportcode,'CHB_PRD_PERIODYIELD' htmlindex from dual
	union all select '10' reportcode,'CHB_PRD_FEE_DEAL' htmlindex from dual
	union all select '11' reportcode,'CHB_ASSET_INFO' htmlindex from dual
	union all select '12' reportcode,'CHB_INVEST_TRADE' htmlindex from dual
	union all select '13' reportcode,'CHB_BOT_AST_POS' htmlindex from dual
	union all select '14' reportcode,'CHB_ASSET_INDEX' htmlindex from dual
	union all select '15' reportcode,'CHB_SUBJECT_BALANCE' htmlindex from dual
	union all select '16' reportcode,'MST_BOND_CREDIT_RATING' htmlindex from dual
	union all select '17' reportcode,'MST_CUSTOMER_INFO' htmlindex from dual
	union all select '18' reportcode,'CHB_CPROD_BALANCE' htmlindex from dual
	union all select '19' reportcode,'SALE_CUST_SVRREPORT' htmlindex from dual
	union all select '42' reportcode,'CHB_SALER_INST_INFO' htmlindex from dual
	union all select '43' reportcode,'CHB_SALER_IDEN_INFO' htmlindex from dual
	union all select '44' reportcode,'CHB_SALER_REW_PENA_INFO' htmlindex from dual
	)


	select c.htmlindex as interfFileType,
	(select count(1) from chb_file_read_monitor_info a
	where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
	and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
	and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}


	) as accessFilenum,/*接入文件*/
	(select count(1) from chb_file_read_monitor_info a
	where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
	and a.FILE_HANDLE_STATUS = '03'/*异常结束*/
	and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
	and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}


	) as exceptionnum,/*异常结束个数*/
	(select count(1) from chb_file_read_monitor_info a
	where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
	and a.FILE_HANDLE_STATUS = '02'/*正常结束*/
	and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
	and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}


	) as normalnum,/*正常结束个数*/
	nvl((select sum(nvl(a.FILE_DATA_COUNT,0)) from chb_file_read_monitor_info a
	where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
	and a.FILE_HANDLE_STATUS = '02'/*正常结束*/
	and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
	and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}


	),0) as datanum /*数据接入总数*/
	from htmlreport c
	left join chb_file_read_monitor_info b
	on b.HANDLE_FILE_TYPE = c.reportcode
	and to_char(b.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
	and to_char(b.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}


    group by b.HANDLE_FILE_TYPE,c.htmlindex
    order by interfFileType desc

	select a.INTERF_TYPE interfFileType, count(a.INTERF_TYPE) as datanum,
	(select count(1) from CHB_INTERF_ERRODATA b
	where b.INTERF_TYPE=a.INTERF_TYPE
	and to_char(b.CREATE_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


        #{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}




			#{item.interfFileType,jdbcType=VARCHAR}


	) as checkfailnum /*检查不通过*/
	from CHB_INTERF_ERRODATA a
	where to_char(a.CREATE_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}




        #{item,jdbcType=VARCHAR}




			#{item.interfFileType,jdbcType=VARCHAR}


	group by INTERF_TYPE

SELECT
count(1) as prodRegistnum
FROM
CHB_PRDRESIST_CODE cpc


WHERE (cpc.REG_CODE is NULL or cpc.REG_CODE = '')



		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}

SELECT
count(1) as mergenum
FROM
CHB_EQU_HOLD_CHECK check1
WHERE check1.OPERATE_STATUS='01'
and to_char(check1.DATA_DATE,'yyyy-mm-dd') <=#{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}

select count(1) from CHB_INVESTHOLD_INFO
	where STATUS = 'A'
	and to_char(HOLD_DATE,'yyyy-mm-dd') = #{searchDate,jdbcType=VARCHAR}

select count(1) from CHB_EQUDET
where STATUS = 'A'
and to_char(EQUITY_CONF_DATE,'yyyy-mm-dd') = #{searchDate,jdbcType=VARCHAR}

with htmlreport as (select '01' reportcode,'CHB_EQU_HOLD' htmlindex from dual
union all select '02' reportcode,'CHB_INVESTHOLD_INFO' htmlindex from dual
union all select '03' reportcode,'CHB_PRD_DECLARE_SUB' htmlindex from dual
union all select '04' reportcode,'CHB_PRD_ISSUE_SUB' htmlindex from dual
union all select '05' reportcode,'CHB_PRD_DEAL_SUB' htmlindex from dual
union all select '06' reportcode,'CHB_PRD_RAISETOT_SUB' htmlindex from dual
union all select '07' reportcode,'CHB_PRD_END_SUB' htmlindex from dual
union all select '08' reportcode,'CHB_ASSET_INFO_SUB' htmlindex from dual
union all select '09' reportcode,'CHB_INVEST_TRADE_SUB' htmlindex from dual
union all select '10' reportcode,'CHB_BOT_AST_POS_SUB' htmlindex from dual
union all select '11' reportcode,'CHB_AST_VAL_SUB' htmlindex from dual
union all select '42' reportcode,'CHB_SALER_INST_SUB' htmlindex from dual
union all select '43' reportcode,'CHB_SALER_IDEN_SUB' htmlindex from dual
union all select '44' reportcode,'CHB_SALER_REW_PENA_SUB' htmlindex from dual

union all select '29' reportcode,'CHB_EQUDET' htmlindex from dual)
select c.htmlindex as interfFileType,
(select count(1) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) as accessFilenum,/*接入文件*/
(select count(1) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and a.FILE_HANDLE_STATUS = '03'/*异常结束*/
and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) as exceptionnum,/*异常结束个数*/
(select count(1) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and a.FILE_HANDLE_STATUS = '02'/*正常结束*/
and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) as normalnum,/*正常结束个数*/
nvl((select sum(nvl(a.FILE_DATA_COUNT,0)) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and a.FILE_HANDLE_STATUS = '02'/*正常结束*/
and to_char(a.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
and to_char(a.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


),0) as datanum /*数据接入总数*/
from htmlreport c
left join chb_file_read_monitor_info b
on b.HANDLE_FILE_TYPE = c.reportcode
and to_char(b.FILE_READ_START_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
and to_char(b.FILE_READ_END_TIME,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


group by b.HANDLE_FILE_TYPE,c.htmlindex
order by interfFileType desc
